// Nhận thông tin từ người dùng (luôn trả về kiểu String)
const customerName = prompt("Nhập tên khách hàng:");

// Xuất thông báo thông thường và xuất cảnh báo ra console
console.log("Đã nhận thông tin khách hàng:", customerName);
console.warn("[WARNING] Kiểm tra kỹ thông tin trước khi thanh toán.");
alert("Chào mừng " + customerName + " đến với rạp phim TRUEMAX!");

const rawPrice = prompt("Nhập giá vé đơn lẻ:"); // Trả về dạng chuỗi, ví dụ: "120000"
const rawQuantity = prompt("Nhập số lượng vé:"); // Trả về dạng chuỗi, ví dụ: "2"

// Ép kiểu chuỗi sang số thực và số nguyên
const ticketPrice = parseFloat(rawPrice);
const ticketQuantity = parseInt(rawQuantity, 10);

// Tính tổng tiền chính xác sau khi ép kiểu
const totalPrice = ticketPrice * ticketQuantity;
console.log("Tổng tiền:", totalPrice);

const filmTitle = "Avatar: The Way of Water";
const seats = 3;
const pricePerSeat = 110000;

// Sử dụng Template Literals với nhúng biểu thức tính toán trực tiếp
const receiptText = `
=== HÓA ĐƠN ĐẶT VÉ ===
Phim: ${filmTitle}
Số ghế: ${seats}
Đơn giá: ${pricePerSeat.toLocaleString("vi-VN")} VNĐ
----------------------
Thành tiền: ${(seats * pricePerSeat).toLocaleString("vi-VN")} VNĐ
`;

console.log(receiptText);

progressive_examples.raw_code:
// Bước 1: Nhận dữ liệu đầu vào từ người dùng qua prompt()
const inputCustomerName = prompt("Mời bạn nhập tên khách hàng:");
const inputTicketCount = prompt("Mời bạn nhập số lượng vé cần mua:");

// Bước 2: Ép kiểu dữ liệu từ String sang Number bằng parseInt()
const ticketCount = parseInt(inputTicketCount, 10);

// Bước 3: Tạo thông báo xác nhận bằng Template Literals
const confirmationMessage = `[XÁC NHẬN VÉ] Khách hàng ${inputCustomerName} đã đăng ký mua ${ticketCount} vé thành công.`;

// Bước 4: Xuất kết quả ra Console
console.log(confirmationMessage);

// Bước 1: Thu thập thông tin đầu vào
const customerName = prompt("Nhập tên khách hàng:");
const movieTitle = prompt("Nhập tên phim:");
const rawQuantity = prompt("Nhập số lượng vé:");
const rawUnitPrice = prompt("Nhập giá vé đơn lẻ (VNĐ):");
const rawDiscountRate = prompt("Nhập tỷ lệ giảm giá (%):");

// Bước 2: Ép kiểu dữ liệu đầu vào sang kiểu số
const quantity = parseInt(rawQuantity, 10);
const unitPrice = parseFloat(rawUnitPrice);
const discountRate = parseFloat(rawDiscountRate);

// Bước 3: Thực hiện tính toán nghiệp vụ
const subTotal = quantity * unitPrice;
const discountAmount = subTotal * (discountRate / 100);
const finalTotal = subTotal - discountAmount;

// Bước 4: Dựng hóa đơn chi tiết sử dụng Template Literals nhiều dòng
const detailedReceipt = `
========================================
       RẠP CHẾU PHIM TRUEMAX CINEMA      
========================================
Khách hàng   : ${customerName}
Phim         : ${movieTitle}
----------------------------------------
Số lượng vé  : ${quantity} vé
Đơn giá      : ${unitPrice.toLocaleString("vi-VN")} VNĐ
Tạm tính     : ${subTotal.toLocaleString("vi-VN")} VNĐ
Giảm giá     : -${discountAmount.toLocaleString("vi-VN")} VNĐ (${discountRate}%)
----------------------------------------
TỔNG THANH TOÁN: ${finalTotal.toLocaleString("vi-VN")} VNĐ
========================================
`;

// Bước 5: In kết quả ra Console và hiển thị alert
console.log(detailedReceipt);
alert(`Đặt vé thành công! Tổng tiền cần thanh toán: ${finalTotal.toLocaleString("vi-VN")} VNĐ`);

// Bước 1: Nhận đầu vào với giá trị mặc định nếu người dùng bỏ qua prompt()
const rawCustomer = prompt("Tên khách hàng:") || "Khách vô danh";
const rawMovie = prompt("Tên phim:") || "Phim chưa chọn";
const rawQuantity = prompt("Số lượng vé:");
const rawPrice = prompt("Giá vé (VNĐ):");

// Bước 2: Ép kiểu và gán giá trị mặc định an toàn (Fallback)
const parsedQuantity = parseInt(rawQuantity, 10);
const parsedPrice = parseFloat(rawPrice);

// Kiểm tra giá trị hợp lệ (nếu nhập chữ hoặc NaN sẽ đưa về 0)
const safeQuantity = Number.isNaN(parsedQuantity) || parsedQuantity < 0 ? 0 : parsedQuantity;
const safePrice = Number.isNaN(parsedPrice) || parsedPrice < 0 ? 0 : parsedPrice;

// Bước 3: Cảnh báo nếu phát hiện dữ liệu bất thường
if (safeQuantity === 0 || safePrice === 0) {
  console.warn("[WARNING] Phát hiện dữ liệu số lượng hoặc giá vé không hợp lệ! Đã tự động điều chỉnh về 0.");
}

// Bước 4: Tính toán tài chính
const totalAmount = safeQuantity * safePrice;

// Bước 5: Hiển thị dữ liệu tổng quan dạng bảng bằng console.table()
const bookingSummary = {
  "Khách hàng": rawCustomer,
  "Phim": rawMovie,
  "Số lượng": safeQuantity,
  "Đơn giá (VNĐ)": safePrice,
  "Tổng tiền (VNĐ)": totalAmount
};

console.log("[HỆ THỐNG TRUEMAX] Dữ liệu đặt vé ghi nhận:");
console.table(bookingSummary);

// Bước 6: Xuất kết quả hóa đơn tổng kết
const finalReceipt = `
[CHI TIẾT HÓA ĐƠN TRUEMAX]
+ Khách hàng: ${rawCustomer.toUpperCase()}
+ Phim: ${rawMovie}
+ Trạng thái: ${totalAmount > 0 ? "HỢP LỆ" : "CẦN KIỂM TRA LẠI"}
+ Tổng thanh toán: ${totalAmount.toLocaleString("vi-VN")} VNĐ
`;

console.log(finalReceipt);

